/**
 * Determinism property tests (Work Order A012 gate 11) — random LEGAL
 * criteria/verdict combinations generated by a seeded LCG
 * (test-support's TestLcg — Numerical Recipes constants, mirroring
 * A010/A011; no new dependencies, no Math.random, no wall-clock reads).
 *
 * Invariants:
 *   P1 aggregate determinism — the aggregate outcome of random criterion
 *      scores is a pure function of (criteria, verdicts): two
 *      independent aggregations agree exactly, and the policy domain
 *      validation never rejects LCG-generated LEGAL scores;
 *   P2 descriptor digest determinism — the same random descriptor
 *      parameters drive two independent builds to identical digests,
 *      and distinct parameter tuples diverge;
 *   P3 criteria digest determinism — random LCG-built criteria rebuild
 *      byte-identically (same digest) and different content diverges;
 *   P4 record score stability (the quality-model rerun requirement) —
 *      same inputs + same seed ⇒ identical EvaluationRecord digest,
 *      across independent constructions;
 *   P5 domain legality — LCG scores drawn from each policy's legal
 *      domain always pass construction (the generator never produces
 *      illegal scores);
 *   P6 verdict-set strictness — random shuffled/mismatched verdict
 *      orders never change the canonical record digest (ordering is
 *      canonicalized) but random SET mismatches always fail.
 */

import { describe, expect, it } from 'vitest';
import { aggregateCriterionVerdicts, createEvaluationRecord } from './record.js';
import { createEvaluationCriteria } from './criteria.js';
import { createEvaluatorDescriptor } from './descriptor.js';
import { EVALUATION_ERROR_CODES } from './errors.js';
import type { CriterionVerdictInput } from './record.js';
import {
  TestLcg,
  makeCriteriaInput,
  makeDescriptorInput,
  makeVerdicts,
} from './test-support.js';

const SEEDS = [1, 42, 20260926, 777, 314159];
const T0 = '2026-03-01T12:00:00.000Z';
const T1 = '2026-03-01T12:00:01.000Z';

/** Legal random scores for the given policy domain. */
function legalScores(rng: TestLcg, policy: 'weighted-sum' | 'pass-threshold' | 'rubric-level', count: number): number[] {
  const scores: number[] = [];
  for (let index = 0; index < count; index += 1) {
    switch (policy) {
      case 'weighted-sum':
        scores.push(Math.round(rng.next() * 100) / 100); // 0..1 quantized
        break;
      case 'pass-threshold':
        scores.push(rng.bool() ? 1 : 0);
        break;
      case 'rubric-level':
        scores.push(1 + rng.int(5));
        break;
    }
  }
  return scores;
}

function randomPolicy(rng: TestLcg): 'weighted-sum' | 'pass-threshold' | 'rubric-level' {
  const policies = ['weighted-sum', 'pass-threshold', 'rubric-level'] as const;
  return policies[rng.int(3)] as (typeof policies)[number];
}

async function randomRun(seed: number) {
  const rng = new TestLcg(seed);
  const policy = randomPolicy(rng);
  const entryCount = 2 + rng.int(4); // 2..5 criteria
  const passAt =
    policy === 'rubric-level' ? 1 + rng.int(5) : Math.round((0.2 + rng.next() * 0.79) * 100) / 100;
  const criteria = await createEvaluationCriteria(
    makeCriteriaInput({
      criteriaId: `criteria-prop-${String(seed)}`,
      aggregation: policy,
      passAt,
      entryCount,
    }),
  );
  const scores = legalScores(rng, policy, entryCount);
  return { rng, policy, criteria, scores, entryCount };
}

describe('property: aggregate-outcome determinism under random criterion scores (P1)', () => {
  for (const seed of SEEDS) {
    it(`seed ${String(seed)}: aggregating the same random verdicts twice yields the identical outcome`, async () => {
      const { criteria, scores } = await randomRun(seed);
      const verdicts = makeVerdicts(criteria.entries.length, { scores });
      const a = aggregateCriterionVerdicts(criteria, verdicts);
      const b = aggregateCriterionVerdicts(criteria, verdicts);
      expect(a).toEqual(b);
      expect(a.score).toBe(b.score);
      expect(a.outcome).toBe(b.outcome);
      expect(a.outcome === 'meets-criteria' || a.outcome === 'below-criteria').toBe(true);
    });
  }
});

describe('property: descriptor digest determinism (P2)', () => {
  for (const seed of SEEDS) {
    it(`seed ${String(seed)}: two independent builds of the same random descriptor are byte-identical`, async () => {
      const rng = new TestLcg(seed);
      const kinds = ['deterministic-test', 'rubric', 'model-based', 'expert', 'simulation', 'comparative', 'adversarial'] as const;
      const kind = kinds[rng.int(7)] as (typeof kinds)[number];
      const human = rng.bool();
      const input = makeDescriptorInput({
        evaluatorId: `eval-prop-${String(seed)}`,
        version: `${1 + rng.int(3)}.${rng.int(5)}.${rng.int(7)}`,
        kind,
        confidence: Math.round(rng.next() * 100) / 100,
        requiresHuman: human,
        deterministic: !human,
        seeded: rng.bool(),
      });
      const a = await createEvaluatorDescriptor(input);
      const b = await createEvaluatorDescriptor(input);
      expect(a.digest).toBe(b.digest);
      // different confidence under the same identity ⇒ different digest
      const variant = await createEvaluatorDescriptor({
        ...input,
        confidence: (input.confidence + 0.01) % 1,
      });
      expect(variant.digest).not.toBe(a.digest);
    });
  }
});

describe('property: criteria digest determinism (P3)', () => {
  for (const seed of SEEDS) {
    it(`seed ${String(seed)}: random criteria rebuild byte-identically; mutated weights diverge`, async () => {
      const rng = new TestLcg(seed);
      const entryCount = 2 + rng.int(3);
      const input = makeCriteriaInput({
        criteriaId: `criteria-prop-${String(seed)}`,
        version: `${1 + rng.int(2)}.${rng.int(4)}.0`,
        entryCount,
      });
      const a = await createEvaluationCriteria(input);
      const b = await createEvaluationCriteria(input);
      expect(a.digest).toBe(b.digest);
      const mutated = await createEvaluationCriteria({
        ...input,
        entries: input.entries.map((entry, index) =>
          index === 0 ? { ...entry, weight: entry.weight + 0.5 } : entry,
        ),
      });
      expect(mutated.digest).not.toBe(a.digest);
    });
  }
});

describe('property: record score stability under rerun (P4 — quality model)', () => {
  for (const seed of SEEDS) {
    it(`seed ${String(seed)}: same inputs + same seed ⇒ identical EvaluationRecord digest`, async () => {
      const { criteria, scores } = await randomRun(seed);
      const base = {
        evaluatorRef: criteria.digest,
        caseRef: 'a'.repeat(64),
        trajectoryRef: 'b'.repeat(64),
        criteriaRef: criteria.digest,
        seed: `seed-${String(seed)}`,
        confidence: 0.8,
        limitations: null,
        startedAt: T0,
        finishedAt: T1,
        provenance: { executedBy: 'evaluator-instance-01', recordedAt: T1, notes: null },
      };
      const a = await createEvaluationRecord({ ...base, verdicts: makeVerdicts(criteria.entries.length, { scores }) }, criteria);
      const b = await createEvaluationRecord({ ...base, verdicts: makeVerdicts(criteria.entries.length, { scores }) }, criteria);
      expect(a.digest).toBe(b.digest);
      expect(a.aggregate).toEqual(b.aggregate);
      // the record digest commits to the seed: different seed ⇒ different digest
      const c = await createEvaluationRecord(
        {
          ...base,
          seed: `seed-${String(seed + 1000)}`,
          verdicts: makeVerdicts(criteria.entries.length, { scores }),
        },
        criteria,
      );
      expect(c.digest).not.toBe(a.digest);
    });
  }
});

describe('property: LCG domain legality (P5)', () => {
  for (const seed of SEEDS.slice(0, 3)) {
    it(`seed ${String(seed)}: every LCG-legal score set constructs a valid record`, async () => {
      const { criteria, scores } = await randomRun(seed);
      const record = await createEvaluationRecord(
        {
          evaluatorRef: 'c'.repeat(64),
          caseRef: 'a'.repeat(64),
          trajectoryRef: 'b'.repeat(64),
          criteriaRef: criteria.digest,
          seed: `seed-${String(seed)}`,
          verdicts: makeVerdicts(criteria.entries.length, { scores }),
          confidence: 0.5,
          limitations: null,
          startedAt: T0,
          finishedAt: T1,
          provenance: { executedBy: 'evaluator-instance-01', recordedAt: T1, notes: null },
        },
        criteria,
      );
      expect(record.digest).toMatch(/^[0-9a-f]{64}$/);
      expect(record.aggregate.score).toBeGreaterThanOrEqual(0);
    });
  }
});

describe('property: verdict ordering is canonical, set mismatches always fail (P6)', () => {
  for (const seed of SEEDS.slice(0, 3)) {
    it(`seed ${String(seed)}: shuffled verdict order ⇒ same digest; set mismatch ⇒ CRITERION_MISMATCH`, async () => {
      const rng = new TestLcg(seed * 31 + 7);
      const { criteria, scores } = await randomRun(seed);
      const verdicts = makeVerdicts(criteria.entries.length, { scores });
      const shuffled = [...verdicts];
      for (let i = shuffled.length - 1; i > 0; i -= 1) {
        const j = rng.int(i + 1);
        const a = shuffled[i]!;
        const b = shuffled[j]!;
        shuffled[i] = b;
        shuffled[j] = a;
      }
      const base = {
        evaluatorRef: 'c'.repeat(64),
        caseRef: 'a'.repeat(64),
        trajectoryRef: 'b'.repeat(64),
        criteriaRef: criteria.digest,
        seed: `seed-${String(seed)}`,
        confidence: 0.5,
        limitations: null,
        startedAt: T0,
        finishedAt: T1,
        provenance: { executedBy: 'evaluator-instance-01', recordedAt: T1, notes: null },
      };
      const ordered = await createEvaluationRecord({ ...base, verdicts }, criteria);
      const reordered = await createEvaluationRecord({ ...base, verdicts: shuffled }, criteria);
      expect(reordered.digest).toBe(ordered.digest);

      const missing: CriterionVerdictInput[] = verdicts.slice(0, verdicts.length - 1);
      await expect(createEvaluationRecord({ ...base, verdicts: missing }, criteria)).rejects.toThrowError(
        expect.objectContaining({ code: EVALUATION_ERROR_CODES.CRITERION_MISMATCH }),
      );
    });
  }
});
